python3 -I - <<'PY'
import json,re,collections
from pathlib import Path
rows=[json.loads(x) for x in Path('/workspace/results/run100/val_generations/100.jsonl').read_text().splitlines()]
counts=collections.Counter(); examples={}
strict=re.compile(r'#### (\-?[0-9\.\,]+)')
wide=re.compile(r'####\s*([-+]?\d[\d,]*(?:\.\d+)?)')
for i,r in enumerate(rows):
 a=wide.findall(r['output']); s=strict.findall(r['output'][-300:])
 if not a: continue
 ans=a[-1].replace(',','')
 try: correct=float(ans)==float(r['gts'].replace(',',''))
 except: correct=False
 if correct and not r['score']:
  reason=[]
  if not s: reason.append('strict_no_match')
  elif s[-1].replace(',','') != r['gts']: reason.append('string_unequal')
  else: reason.append('other')
  key='+'.join(reason);counts[key]+=1;examples.setdefault(key,[]).append((i,ans,r['output'][-200:]))
print(counts)
for k,v in examples.items():
 print('\n',k)
 for x in v[:20]: print(x)
PY

